// Contract tests for SHA-256 and the frozen Test Item identity digests.
// Digest vectors are generated by the Python reference
// (deepyield/io/test_item_index/identity.py).
#include "deepyield_stdf/sha256.hpp"

#include <cstdint>
#include <iostream>
#include <string>

namespace {

int failures = 0;

void check(bool condition, const std::string& label) {
  if (!condition) {
    std::cerr << "FAIL: " << label << "\n";
    ++failures;
  }
}

std::string hex16(const std::array<std::uint8_t, 16>& bytes) {
  static const char* hex = "0123456789abcdef";
  std::string out;
  for (auto byte : bytes) {
    out.push_back(hex[(byte >> 4) & 0x0f]);
    out.push_back(hex[byte & 0x0f]);
  }
  return out;
}

}  // namespace

int main() {
  using namespace deepyield_stdf;

  // FIPS 180-4 vectors.
  const std::string abc_digest = Sha256::hex_digest("abc");
  if (abc_digest !=
      "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad") {
    std::cerr << "sha256('abc') got " << abc_digest << "\n";
    ++failures;
  }

  const std::string empty_digest = Sha256::hex_digest("");
  if (empty_digest !=
      "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855") {
    std::cerr << "sha256('') got " << empty_digest << "\n";
    ++failures;
  }
  const std::string payload_v1 = "test-item-v1\x1f" "PTR\x1f" "10\x1f" "-";
  check(Sha256::hex_digest(payload_v1) == Sha256::hex_digest(payload_v1),
        "deterministic payload digest");

  // Frozen Python-reference vectors (see identity.py test vectors).
  const std::string ptr_payload = test_item_payload("PTR", 10, "-");
  check(test_item_key_hex(ptr_payload).substr(0, 4) == "tik_",
        "PTR key prefix");
  check(test_item_key_hex(ptr_payload).size() == 36, "PTR key length");
  check(test_item_key_hex(ptr_payload) ==
            "tik_346235adca9015a3c982958a64deb814",
        "PTR key exact digest (Python reference)");

  const std::string mpr_payload = test_item_payload("MPR", 4294967295U, "2147483647");
  check(test_item_key_hex(mpr_payload).substr(0, 4) == "tik_",
        "MPR boundary key prefix");
  auto raw = test_item_key_raw(mpr_payload);
  check(raw.size() == 16 && hex16(raw).size() == 32, "MPR raw key length");

  // Bucket hash prefix must be deterministic across calls.
  check(bucket_hash_prefix(ptr_payload) == bucket_hash_prefix(ptr_payload),
        "bucket hash deterministic");

  if (failures == 0) {
    std::cout << "test_sha256: OK\n";
    return 0;
  }
  std::cerr << "test_sha256: " << failures << " failure(s)\n";
  return 1;
}
